@file:OptIn(kotlinx.coroutines.ExperimentalCoroutinesApi::class)
package app.kari.android

import org.junit.Test
import org.junit.Assert.*
import org.json.JSONObject
import kotlinx.coroutines.*
import kotlinx.coroutines.test.*

class CompanionPolicyTest {
    private val catalog=listOf(IdleScene("a","a","a",false,"pose_neutral",emptyList()),IdleScene("b","b","b",true,null,emptyList()))
    @Test fun profileDefaultsAndSafetyCannotBeOverridden(){val p=PersonalityProfile.parse("""{"name":"小路","boundaries":{"doNotMoveWhenUnarmed":false}}""");assertEquals("小路",p.name);assertEquals(8,p.coreTraits.size);assertTrue(p.json().getJSONObject("boundaries").getBoolean("doNotMoveWhenUnarmed"));assertEquals(p,PersonalityProfile.parse(p.json().toString()))}
    @Test fun profileRejectsTypesAndRanges(){for(s in listOf("{}","""{"name":true}""","""{"identity":""}""","""{"coreTraits":{"curiosity":true}}""","""{"coreTraits":{"curiosity":1.01}}""","""{"speechStyle":{"shortReplies":1}}""","""{"behaviorStyle":[]}""")){assertThrows(Exception::class.java){PersonalityProfile.parse(s)}}}
    @Test fun companionRoundTripAndUnsupportedVersions(){val c=CompanionConfiguration();assertEquals(c,CompanionConfiguration.parse(c.json().toString(),setOf("a")));assertThrows(Exception::class.java){CompanionConfiguration.parse(c.json().put("schemaVersion",2).toString(),setOf("a"))};assertThrows(Exception::class.java){CompanionConfiguration.parse(c.json().put("schemaVersion","1").toString(),setOf("a"))}}
    @Test fun completeImportRejectsUnknownScenesAndInvalidSettings(){val c=CompanionConfiguration();for(o in listOf(c.json().put("wake",WakeSettings().json().put("silenceTimeout",0)),c.json().put("idle",IdleSceneSettings(scenes=mapOf("unknown" to IdleSceneOptions())).json()),c.json().put("behavior",BehaviorSettings().json().put("thoughtsPerMinute",1.5)),c.json().put("idle",IdleSceneSettings().json().put("first",JSONObject().put("minimum",20).put("maximum",10))))){assertThrows(Exception::class.java){CompanionConfiguration.parse(o.toString(),setOf("a"))}}}
    @Test fun defaultSettingsKeepBodyAndCloudProactivityOff(){val c=CompanionConfiguration();assertTrue(c.behavior.enabled);assertFalse(c.behavior.idleBody);assertFalse(c.behavior.proactiveAI);assertFalse(c.behavior.proactiveExpression);assertFalse(c.wake.enabled);assertEquals(60.0,c.wake.silenceTimeout,0.0)}
    @Test fun lifeMonotonicTimeAndNoBackgroundCatchup(){val life=LifeEngine();life.begin(0.0,IdleSceneSettings());life.tick(1.0,PersonalityProfile(),60.0);assertEquals(.749,life.state.energy,.000001);life.suspendClock();val paused=life.state;life.tick(301.0,PersonalityProfile(),60.0);assertEquals(paused,life.state);life.tick(302.0,PersonalityProfile(),60.0);assertFalse(life.state.sleeping)}
    @Test fun interactionWakesAndUnknownInputsAreNotInferred(){val life=LifeEngine();life.begin(0.0,IdleSceneSettings());life.tick(100.0,PersonalityProfile(),60.0);assertTrue(life.state.sleeping);life.event("wake",100.0);assertFalse(life.state.sleeping);assertEquals("interaction",life.state.attention);assertEquals(0.0,life.state.boredom,0.0)}
    @Test fun scenesRespectCooldownAvailabilityAndBodyPermission(){val life=LifeEngine();var s=IdleSceneSettings();val p=PersonalityProfile();life.begin(0.0,s);assertNull(life.select(2.0,catalog,s,p,false,false,false,true));assertEquals("a",life.select(4.0,catalog,s,p,false,false,false,true)?.id);assertNull(life.select(5.0,catalog,s,p,false,false,false,true));assertNull(life.select(35.0,listOf(catalog[1]),s,p,true,true,false,true));assertEquals("b",life.select(35.0,listOf(catalog[1]),s,p,true,false,false,true)?.id);s=s.copy(scenes=mapOf("a" to IdleSceneOptions(enabled=false),"b" to IdleSceneOptions(weight=0.0)));assertNull(life.select(100.0,catalog,s,p,true,false,false,true));assertEquals("no_eligible_scene",life.state.reason)}
    @Test fun sleepingScenesAndWeightedSelection(){val life=LifeEngine();val p=PersonalityProfile();val s=IdleSceneSettings(scenes=mapOf("a" to IdleSceneOptions(weight=0.0),"b" to IdleSceneOptions(weight=2.0)));life.begin(0.0,s);assertEquals("b",life.select(5.0,catalog,s,p,true,false,false,true,sample=.99)?.id);life.tick(70.0,p,60.0);assertNull(life.select(70.0,catalog,s,p,true,false,false,true))}
    @Test fun thinkingAndExpressionAreBounded(){val b=BehaviorCoordinator();b.begin(0.0,IdleSceneSettings());assertTrue(b.admitThought(0.0,2));assertFalse(b.admitThought(1.0,2));assertTrue(b.admitThought(6.0,2));assertFalse(b.admitThought(30.0,2));assertTrue(b.admitThought(61.0,2));assertTrue(b.admitExpression(0.0,1.0));assertFalse(b.admitExpression(59.0,1.0));assertTrue(b.admitExpression(60.0,1.0));repeat(1000){b.event(it.toDouble(),"event");b.decision(it.toDouble(),"rule","reason")};assertEquals(500,b.events.size);assertEquals(100,b.decisions.size)}
    @Test fun wakeBufferPreRollOrderAndExactlyOnce(){val w=WakePolicy();w.wait(0.0);w.append(ByteArray(40000){1},1.0,false);assertEquals(32000,w.bufferedBytes);val token=w.wake(2.0)!!;w.append(byteArrayOf(2,3),2.0,false);val all=w.connected(token,3.0)!!;assertEquals(32002,all.size);assertEquals(2,all[32000].toInt());assertNull(w.connected(token,3.0));assertArrayEquals(byteArrayOf(4),w.append(byteArrayOf(4),3.0,false));assertEquals(0,w.bufferedBytes)}
    @Test fun overflowNeverSendsPartialQuestionAndOldConnectCannotResume(){val w=WakePolicy();w.wait(0.0);val token=w.wake(2.0)!!;w.append(ByteArray(256002),2.0,false);assertTrue(w.overflow);assertEquals(0,w.bufferedBytes);w.append(byteArrayOf(1),3.0,false);assertEquals(0,w.connected(token,4.0)!!.size);w.stop();assertNull(w.connected(token,5.0));assertEquals(WakePhase.STOPPED,w.phase)}
    @Test fun repeatedWakeAndBusyTimeout(){val w=WakePolicy();w.wait(0.0);val token=w.wake(0.0)!!;assertNull(w.wake(0.1));w.connected(token,1.0);assertFalse(w.timedOut(100.0,60.0,true));w.activity(100.0);assertFalse(w.timedOut(159.0,60.0,false));assertTrue(w.timedOut(160.0,60.0,false));w.stop(suspended=true);assertNull(w.append(byteArrayOf(1),170.0,true));assertEquals(0,w.bufferedBytes)}
    @Test fun slowStopAckCannotGrantCancelledMotion()=runTest {val ready=kotlinx.coroutines.flow.MutableStateFlow(true);val ack=CompletableDeferred<Unit>();val robot=object:RobotTransport{override val ready=ready;override suspend fun send(payload:JSONObject):JSONObject{ack.await();return JSONObject().put("type","ack")}};val a=MotionArbiter(robot);a.arm(true);var granted=false;val job=launch{runCatching{a.acquire(MotionSource.IDLE)}.onSuccess{granted=true}};runCurrent();a.revoke();ack.complete(Unit);job.join();assertFalse(granted);assertNull(a.owner)}
    @Test fun firstOwnerRequiresConfirmedStop()=runTest {val b=MotionTest.Transport();val a=MotionArbiter(b);a.arm(true);b.fail=true;assertThrows(Exception::class.java){runBlocking{a.acquire(MotionSource.IDLE)}};assertNull(a.owner);assertFalse(a.allowed)}
    @Test fun stopInsideSceneKeepsLeaseButEmergencyStopInvalidatesIt()=runTest {val b=MotionTest.Transport();val a=MotionArbiter(b);a.arm(true);val lease=a.acquire(MotionSource.SCENARIO);a.send(JSONObject().put("type","stop"),MotionSource.SCENARIO,lease);assertTrue(a.valid(MotionSource.SCENARIO,lease));a.stop();assertFalse(a.valid(MotionSource.SCENARIO,lease))}

}
